    "shortDescription": "سبعة عشر يومًا وستة عشر ليلة تجمع بين المواقع الثقافية ومناظر التلال والحياة البرية والشواطئ الجنوبية.",
    "overview": "استكشف هابارانا وسيجيريا وهيريوادونا ومينيريا، مع تجربة ركوب المنطاد وزيارة أنورادابورا. اكتشف معبد كهف دامبولا، ومعبد السن المقدس في كاندي، وعرضًا ثقافيًّا، وبرج أمبولواوا، والحديقة النباتية الملكية. تابع رحلتك عبر نوارا إليا لزيارة شلالات رامبودا وبحيرة غريغوري ومزرعة الفراولة، ثم توجه إلى إيلا لزيارة جسر التسعة أقواس وقمة آدم المصغرة وشلالات رافانا. أما الجزء الجنوبي فيضم منتزه يالا الوطني وميريسا وقلعة غالي الهولندية ومركز تربية السلاحف البحرية في كوسغودا ورحلة بحرية عند غروب الشمس في بينتوتا. واختتم رحلتك بجولة سياحية في مدينة كولومبو، والتسوق، وتذوق الأطعمة الشعبية في الشوارع.",
